m=np.array([10.,1.,1.]);r=np.array([6.5,7.,7.5])
for t in range(96):
 if t%4==0:print(t+1,np.round(p,1),np.round(v,2))
 p+=v
 v*=.997
 # collide 3 passes
 for z in range(3):
  for i in range(3):
   for j in range(i+1,3):
    d=p[j]-p[i];dist=np.linalg.norm(d);rs=r[i]+r[j]
